import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  sin,
  fract,
  dot,
  texture,
  length,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusGeometry, TorusKnotGeometry, DirectionalLight, PointLight } = THREE;

  const root = new Group();
  root.name = 'pedestal-material-study';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const PAPER = colors.paper ?? '#e8ecf2';
  const INK = colors.ink ?? '#16161d';
  const SURFACE = colors.surface ?? '#14141a';
  const ACCENT = colors.accent ?? '#ff2a38';
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  const disposables = [];
  const primitiveResults = [];

  // ---------- Backdrop ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const t = uv().y;
  const cA = color(stops[0]?.hex ?? '#0b0b10');
  const cB = color(stops[1]?.hex ?? '#101017');
  const cC = color(stops[2]?.hex ?? '#16161d');
  const mixAB = mix(cA, cB, smoothstep(0.0, stops[1]?.at ?? 0.7, t));
  const finalGradient = mix(mixAB, cC, smoothstep(stops[1]?.at ?? 0.7, stops[2]?.at ?? 1.0, t));
  backdropMat.colorNode = finalGradient;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(() => { backdropGeo.dispose(); backdropMat.dispose(); });

  // ---------- Contact shadow ----------
  const shadowGeo = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const shadowUv = uv();
  const distFromCenter = length(shadowUv.sub(vec2(0.5, 0.5)));
  const shadowFalloff = smoothstep(0.3667, 0.5, distFromCenter);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = mix(0.6, 0.0, shadowFalloff);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -0.36, 0);
  root.add(contactShadow);
  disposables.push(() => { shadowGeo.dispose(); shadowMat.dispose(); });

  // ---------- Pedestal ----------
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 48);
  const pedestalMat = new MeshPhysicalNodeMaterial({
    color: SURFACE,
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.6, 0);
  root.add(pedestal);
  disposables.push(() => { pedestalGeo.dispose(); pedestalMat.dispose(); });

  // Chamfered top rim catching key light
  const chamferGeo = new TorusGeometry(1.1, 0.03, 12, 48);
  const chamferMat = new MeshPhysicalNodeMaterial({
    color: PAPER,
    roughness: 0.4,
    metalness: 0.6,
  });
  const chamfer = new Mesh(chamferGeo, chamferMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.set(0, -0.35, 0);
  root.add(chamfer);
  disposables.push(() => { chamferGeo.dispose(); chamferMat.dispose(); });

  // ---------- Torus knot material study ----------
  const knotGroup = new Group();
  knotGroup.position.set(0, 0.4, 0);
  root.add(knotGroup);

  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial({
    color: '#cfd2d6',
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    envMapIntensity: 0.7,
  });
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2; // rotated 90deg to tube direction

  // Base roughness jitter + scratch normal perturbation (procedural, node-only)
  const jitterSeed = dot(uv(), vec2(12.9898, 78.233));
  const jitter = fract(sin(jitterSeed).mul(43758.5453)).mul(0.02).sub(0.01);
  const baseRoughnessNode = jitter.add(0.55);
  knotMat.roughnessNode = baseRoughnessNode;

  const scratchFreq = 220.0;
  const scratch = sin(uv().x.mul(scratchFreq)).mul(0.15);
  const perturbedNormal = vec3(scratch, scratch.mul(0.3), 1.0).normalize();
  knotMat.normalNode = perturbedNormal;

  const knot = new Mesh(knotGeo, knotMat);
  knotGroup.add(knot);
  disposables.push(() => { knotGeo.dispose(); knotMat.dispose(); });

  // Async: swap in brushed-metal roughness map, center 0.9, map multiplies (swap-proof)
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
      const mapNode = texture(tex).r.mul(0.55).div(0.9).add(jitter);
      knotMat.roughnessNode = mapNode;
      knotMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------- Node-local lights (rim + accent glint) ----------
  const rimLight = new DirectionalLight(PAPER, 0.8);
  rimLight.position.set(-2.5, 2.2, -2.0);
  root.add(rimLight);

  const accentLight = new PointLight(ACCENT, 0.4, 6);
  accentLight.position.set(1.4, 0.6, 1.6);
  root.add(accentLight);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let headlineObj = null;
  let captionObj = null;
  for (const item of items) {
    if (item.role === 'headline') {
      headlineObj = ctx.fontAtlas.createText(item.text ?? 'Material study 03', {
        fontSize: item.typography?.fontSize ?? 68,
        color: PAPER,
        align: 'center',
      });
      headlineObj.position.set(0, -1.2, 0.2);
      root.add(headlineObj);
    } else if (item.role === 'caption') {
      captionObj = ctx.fontAtlas.createText(item.text ?? 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
        fontSize: item.typography?.fontSize ?? 18,
        color: PAPER,
        align: 'center',
        letterSpacingPx: 1.4,
      });
      captionObj.position.set(0, -1.6, 0.2);
      root.add(captionObj);
    }
  }

  // ---------- Cinematic primitives ----------
  const primitiveSpecs = config.cinematicPrimitives ?? [];
  for (const p of primitiveSpecs) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const target = p.name === 'orbit' ? knotGroup : root;
      const result = fn(target, p.params ?? {});
      if (result) primitiveResults.push(result);
    }
  }

  // ---------- Idle weighted-settle entrance ----------
  root.scale.set(0.96, 0.96, 0.96);
  const tl = gsap.timeline();
  tl.to(root.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const r of primitiveResults) {
      try { r.cleanup?.(); } catch (e) { /* noop */ }
    }
    for (const d of disposables) {
      try { d(); } catch (e) { /* noop */ }
    }
    if (headlineObj) {
      headlineObj.geometry?.dispose?.();
      headlineObj.material?.dispose?.();
    }
    if (captionObj) {
      captionObj.geometry?.dispose?.();
      captionObj.material?.dispose?.();
    }
  };

  return root;
}
